package ua.empirecraft.feudal;
import java.sql.SQLException;
import java.util.*;
import static ua.empirecraft.feudal.Database.*;
import static ua.empirecraft.feudal.Model.*;
import ua.empirecraft.feudal.FeudalService.Actor;

public final class DiplomacyService {
    public enum Type {ALLIANCE("Союз"),NAP("Ненапад"),TRADE("Торговельна угода"),PASSAGE("Право проходу");final String label;Type(String label){this.label=label;}static Type parse(String text){return switch(text.toLowerCase(Locale.ROOT)){case "союз","alliance" -> ALLIANCE;case "ненапад","nap" -> NAP;case "торгівля","trade" -> TRADE;case "прохід","passage" -> PASSAGE;default -> throw new IllegalArgumentException("Тип: союз, ненапад, торгівля або прохід.");};}}
    private final FeudalService s;private final Database db;
    public DiplomacyService(FeudalService s) throws SQLException {this.s=s;db=s.db;
        db.execute("CREATE TABLE IF NOT EXISTS diplomacy (id VARCHAR(36) PRIMARY KEY,a VARCHAR(80),b VARCHAR(80),kind VARCHAR(16),terms CLOB,days INT,signer_a VARCHAR(36),signer_b VARCHAR(36),status VARCHAR(16),created BIGINT,proposal_expires BIGINT,starts BIGINT,ends BIGINT,ended BIGINT,reason VARCHAR(200))");
        db.execute("CREATE TABLE IF NOT EXISTS diplomacy_history (seq BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id VARCHAR(36),at_time BIGINT,actor VARCHAR(80),event VARCHAR(32),detail CLOB)");db.execute("CREATE INDEX IF NOT EXISTS diplomacy_parties ON diplomacy(a,b,status)");}
    private Estate ruler(Actor actor,String id) throws SQLException {Estate e=s.estate(id);require(e.active()&&e.kind()==Kind.KINGDOM&&Objects.equals(e.lord(),actor.id()),"Підписувати може лише чинний правитель держави.");return e;}
    private void log(String id,Actor actor,String event,String detail) throws SQLException {db.execute("INSERT INTO diplomacy_history(id,at_time,actor,event,detail) VALUES(?,?,?,?,?)",id,s.now(),actor.id(),event,detail);s.audit(actor,"DIPLOMACY_"+event,id+" "+detail);}
    public Map<String,Object> get(String id) throws SQLException {var row=db.one("SELECT * FROM diplomacy WHERE id=?",id);require(row!=null,"Договір не знайдено.");return row;}
    public String propose(Actor actor,String from,String to,Type type,int days,String terms){return db.transaction(()->{
        ruler(actor,from);Estate target=s.estate(to);require(target.active()&&target.kind()==Kind.KINGDOM&&!from.equals(to),"Потрібні дві різні активні держави.");require(!Objects.equals(s.estate(from).lord(),target.lord()),"Потрібні різні правителі сторін.");require(days>=1&&days<=365,"Строк: 1–365 днів.");require(terms!=null&&terms.length()>=3&&terms.length()<=512&&terms.chars().noneMatch(Character::isISOControl)&&!terms.contains("§"),"Умови: 3–512 друкованих знаків.");
        require(db.one("SELECT id FROM diplomacy WHERE kind=? AND status IN ('PROPOSED','ACTIVE') AND ((a=? AND b=?) OR (a=? AND b=?))",type.name(),from,to,to,from)==null,"Договір цього типу вже існує.");String id=UUID.randomUUID().toString();db.execute("INSERT INTO diplomacy VALUES(?,?,?,?,?,?,?,NULL,'PROPOSED',?,?,0,0,0,NULL)",id,from,to,type.name(),terms,days,actor.id(),s.now(),s.now()+2*FeudalService.DAY);log(id,actor,"OFFER",type.label+"; "+days+" днів; "+terms);return id;
    });}
    public void sign(Actor actor,String id){db.transaction(()->{var p=get(id);require("PROPOSED".equals(string(p,"status"))&&s.now()<number(p,"proposal_expires"),"Пропозиція вже не діє.");Estate a=s.estate(string(p,"a")),b=ruler(actor,string(p,"b"));require(a.active()&&Objects.equals(a.lord(),string(p,"signer_a"))&&!Objects.equals(a.lord(),b.lord()),"Змінився правитель; потрібна нова пропозиція.");long end=Math.addExact(s.now(),Math.multiplyExact(number(p,"days"),FeudalService.DAY));db.execute("UPDATE diplomacy SET signer_b=?,status='ACTIVE',starts=?,ends=? WHERE id=?",actor.id(),s.now(),end,id);log(id,actor,"SIGN","Обидві сторони підписали; до "+end);return null;});}
    public void end(Actor actor,String id,String reason){db.transaction(()->{var p=get(id);String status=string(p,"status");require(Set.of("ACTIVE","PROPOSED").contains(status),"Договір уже завершено.");Estate a=s.estate(string(p,"a")),b=s.estate(string(p,"b"));require((a.active()&&Objects.equals(a.lord(),actor.id()))||(b.active()&&Objects.equals(b.lord(),actor.id())),"Розірвати може правитель однієї зі сторін.");require(reason!=null&&reason.length()>=3&&reason.length()<=160&&!reason.contains("§")&&reason.chars().noneMatch(Character::isISOControl),"Причина: 3–160 друкованих знаків.");db.execute("UPDATE diplomacy SET status=?,ended=?,reason=? WHERE id=?",status.equals("ACTIVE")?"TERMINATED":"REJECTED",s.now(),reason,id);log(id,actor,"END",reason);return null;});}
    public void tick(){db.transaction(()->{for(var p:db.query("SELECT * FROM diplomacy WHERE status IN ('PROPOSED','ACTIVE')")){boolean pending=string(p,"status").equals("PROPOSED");Estate a=s.estate(string(p,"a")),b=s.estate(string(p,"b"));String reason=!a.active()||!b.active()?"Держава більше не існує":pending&&!Objects.equals(a.lord(),string(p,"signer_a"))?"Змінився правитель до підписання":s.now()>=(pending?number(p,"proposal_expires"):number(p,"ends"))?"Строк дії минув":null;if(reason!=null){String id=string(p,"id");db.execute("UPDATE diplomacy SET status='EXPIRED',ended=?,reason=? WHERE id=?",s.now(),reason,id);log(id,new Actor("система",true),"EXPIRE",reason);}}return null;});}
    public List<Map<String,Object>> list(String nation) throws SQLException {return db.query("SELECT * FROM diplomacy WHERE a=? OR b=? ORDER BY created DESC LIMIT 100",nation,nation);}
    public List<Map<String,Object>> history(String id) throws SQLException {get(id);return db.query("SELECT * FROM diplomacy_history WHERE id=? ORDER BY seq DESC LIMIT 40",id);}
    public boolean peaceful(String a,String b) throws SQLException {return a!=null&&b!=null&&!a.equals(b)&&db.one("SELECT id FROM diplomacy WHERE status='ACTIVE' AND ends>? AND kind IN ('NAP','ALLIANCE') AND ((a=? AND b=?) OR (a=? AND b=?))",s.now(),a,b,b,a)!=null;}
    public String relations(String nation) throws SQLException {var lines=new ArrayList<String>();for(var p:list(nation))if("ACTIVE".equals(string(p,"status"))&&number(p,"ends")>s.now())lines.add(Type.valueOf(string(p,"kind")).label+": "+s.estate(string(p,nation.equals(string(p,"a"))?"b":"a")).name());return lines.isEmpty()?"Немає чинних договорів":String.join("; ",lines);}
}
